// Fictional demo data (Lácteos Agua Clara S.A.S.). Generated by scripts/generate_demo_data.py.
import raw from "@/data/demo/lacteos.json";
import type { Lang } from "@/lib/content";

export type Line = { code: string; qty: number };
export type Product = { code: string; en: string; es: string; unit: "kg" | "unit"; category: string };
export type Client = {
  id: string;
  nit: string;
  legalName: string;
  priceList: string;
  termDays: number;
  city: string;
  points: string[];
};
export type Order = {
  id: string;
  placedOffset: number;
  deliveryOffset: number;
  typedName: string;
  lines: Line[];
  mine?: boolean; // placed by this visitor
};
export type Supplier = {
  id: string;
  nit: string;
  name: string;
  conceptEn: string;
  conceptEs: string;
  termDays: number;
};
export type Receivable = {
  clientId: string;
  invoice: string;
  point: string | null;
  issueOffset: number;
  dueOffset: number;
  original: number;
  balance: number;
  lines: Line[];
  advance?: boolean;
};
export type Payable = {
  supplierId: string;
  invoice: string;
  issueOffset: number;
  dueOffset: number;
  original: number;
  balance: number;
  advance?: boolean;
};

export type ProdProduct = { code: string; en: string; es: string; input: "milk" | "cream"; stdLPerKg: number };
export type ProdBatch = {
  dayOffset: number;
  product: string;
  operator: string;
  inputL: number;
  outputKg: number;
  minutes: number;
  mine?: boolean;
};

type Data = {
  company: { name: string; nit: string; city: string; address: string; phone: string; email: string };
  products: Product[];
  priceLists: Record<string, Record<string, number>>;
  clients: Client[];
  suppliers: Supplier[];
  pendingOrders: Order[];
  receivables: Receivable[];
  payables: Payable[];
  productionProducts: ProdProduct[];
  operators: string[];
  production: ProdBatch[];
};

export const DATA = raw as unknown as Data;

export const productByCode = Object.fromEntries(DATA.products.map((p) => [p.code, p]));

export const productName = (code: string, lang: Lang) => productByCode[code]?.[lang] ?? code;

/** Date `offset` days from today (the demo is always "current"). */
export function dayFromToday(offset: number): Date {
  const d = new Date();
  d.setHours(12, 0, 0, 0);
  d.setDate(d.getDate() + offset);
  return d;
}

export function fmtDate(d: Date, lang: Lang) {
  return d.toLocaleDateString(lang === "es" ? "es-CO" : "en-US", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

export function fmtCOP(n: number) {
  const v = Math.round(n);
  return (v < 0 ? "-$" : "$") + Math.abs(v).toLocaleString("es-CO");
}

export function fmtQty(n: number) {
  return Number.isInteger(n) ? String(n) : n.toLocaleString("es-CO");
}
